from lib import *
S = SS('w45')
steps = [
    step("字节流如何被编号:客户端分三次发 100、250、30 字节(间隔 0.2 秒),服务端每次 recv。用相对序号(减去各自的 ISN)看:SYN 序号 0(占 1 个序号);第一个数据段相对序号 1、载荷 100,服务端随后的 ACK 确认号 101;第二个数据段相对序号 101、载荷 250,确认号 351;第三个相对序号 351、载荷 30,确认号 381;客户端 FIN 的相对序号 381,服务端确认号 382(FIN 也占 1 个序号);服务端自己的 FIN 相对序号 1,客户端最后的 ACK 确认号 2。3 个数据段的“序号 + 载荷”全部出现在随后服务端的确认号里(3 / 3)。规则:序号标的是这个段的第一个字节在字节流里的位置;确认号是“我期望收到的下一个字节的位置”;SYN 和 FIN 各占 1 个序号,所以握手之后的第一个数据字节序号是 ISN + 1。", t=tl(S(1)), mark=lidx(S(1), 'ACK+PSH       101', 'ACK+PSH       351', 'ACK+FIN       381'), done=lidx(S(1), '客户端 ISN =', 'SYN             0', '3 个数据段', '规则'), b=bars([['第一个数据段 · 确认号', 101, '101'], ['第二个数据段 · 确认号', 351, '351'], ['第三个数据段 · 确认号', 381, '381'], ['FIN · 确认号', 382, '382']], 382, mark=[3], done=[0, 1, 2]), kv=KV([['序号', '本段第一个字节的位置'], ['确认号', '期望收到的下一个字节的位置'], ['SYN / FIN', '各占 1 个序号'], ['首个数据字节', 'ISN + 1']], ['确认号'])),
    step("累积确认:下载 4 MiB,服务端发了 196 个数据段(最大载荷 16332 字节),客户端只回了 45 个纯 ACK,平均每 4.4 个数据段回 1 个 ACK。相邻两个 ACK 之间确认号增加的字节数:最小 16332(1 个段)、中位 32664(2 个段)、最大 571620;总共确认了 4194305 字节(4 MiB 加上握手 SYN 占的 1 个序号)。一个 ACK 确认的是“从头到这里的所有字节”,中间少回几个 ACK 不会丢信息;ACK 越稀开销越小,但发送方等到确认的时间可能更久。", t=tl(S(2)), mark=lidx(S(2), '相邻两个 ACK'), done=lidx(S(2), '下载 4194304 字节', '一个 ACK 确认的是'), b=bars([['数据段', 196, '196'], ['纯 ACK', 45, '45'], ['每个 ACK 确认的最小字节数', 16332, '16,332'], ['中位', 32664, '32,664']], 196, mark=[1], done=[0, 2, 3]), kv=KV([['196 个数据段', '45 个纯 ACK(每 4.4 个回 1 个)'], ['每个 ACK', '确认 16,332~571,620 字节'], ['总确认', '4,194,305 = 4 MiB + SYN']], ['每个 ACK'])),
    step("32 位序号会回绕:在 lo0 上发 4.5 GiB(抓包只留头部),0.9 秒传完(约 4934 MiB/s),抓到服务端数据段 263593 个。服务端 ISN 是 1355246696,绝对序号在第 162573 个段之后从 4294960721(距 2^32 只差 6575)回绕到 9757;9757 正好等于 (4294960721 + 它的载荷) 对 2^32 取模。所以比较两个序号“谁在前”不能直接比大小,要看它们的差是否小于 2^31(TCP 实现里的 SEQ_LT 宏);时间戳选项的 PAWS(第 63 篇)就是为了在高速网络里防止回绕后的旧段被当成新段。", t=tl(S(3)), mark=lidx(S(3), '绝对序号在 1 处', '回绕处'), done=lidx(S(3), '传输 4.50 GiB', '所以比较两个序号'), b=bars([['序号空间', 4294967296, '2^32 = 4,294,967,296'], ['回绕前的序号', 4294960721, '4,294,960,721'], ['回绕后的序号', 9757, '9,757']], 4294967296, mark=[2], done=[0, 1]), kv=KV([['4.5 GiB', '0.9 秒传完'], ['回绕', '4294960721 → 9757'], ['比较序号', '看差是否 < 2^31(模 2^32)']], ['回绕'])),
    step("SYN 和 FIN 各占 1 个序号:客户端 SYN 序号 737984981,发 1000 字节后 FIN 的序号 737985982 = ISN + 1 + 1000(验证成立),服务端最后确认客户端的 ACK 号是 1002 = 1(SYN)+ 1000 + 1(FIN);服务端 SYN-ACK 序号 2038976298,发 500 字节后 FIN 的序号 2038976799 = ISN + 1 + 500(成立),客户端最后确认服务端的 ACK 号是 502 = 1 + 500 + 1。每个方向有自己独立的序号空间,一个方向发了多少字节与另一个方向无关。", t=tl(S(4)), mark=lidx(S(4), '客户端:SYN 序号', '服务端:SYN-ACK 序号'), done=lidx(S(4), '一个连接里每个方向'), kv=KV([['客户端方向', 'SYN 1 + 1000 字节 + FIN 1 = 确认号 1002'], ['服务端方向', 'SYN 1 + 500 字节 + FIN 1 = 确认号 502'], ['序号空间', '两个方向各自独立']], ['序号空间'])),
]
A = mkartw('w45', 45, '网络协议,TCP,序号,确认号,累积确认,序号回绕,真实验证,动画演示',
    '逐包验证 TCP 序号 / 确认号:数据段的序号 + 载荷 = 下一个确认号,SYN / FIN 各占 1 个序号;4 MiB 下载 196 个数据段只回 45 个 ACK(累积确认);lo0 上发 4.5 GiB 真的看到序号从 4294960721 回绕到 9757。',
    '序号和确认号到底在数什么?为什么 ACK 可以不是一包一回?32 位序号发满 4 GiB 之后会怎样?这篇逐个包核对序号和确认号的算术,并在回环上真的发 4.5 GiB 看序号回绕。',
    [('+1', 'SYN 和 FIN 各占一个序号:确认号 = 对方发过的字节数 + 2'), ('196 个段 / 45 个 ACK', '下载 4 MiB 时服务端的数据段数和客户端回的纯 ACK 数:平均每 4.4 个段回 1 个'), ('4294960721 → 9757', 'lo0 上发 4.5 GiB 时抓到的序号回绕(2^32 = 4294967296)')],
    [('序号和确认号', '<p>序号 = 本段第一个字节在字节流里的位置;确认号 = 期望收到的下一个字节的位置。SYN 和 FIN 各占 1 个序号。</p>'),
     ('累积确认', '<p>一个 ACK 确认从头到这里的所有字节,所以接收方可以隔几个段才回一个 ACK。</p>'),
     ('回绕', '<p>序号是 32 位的,发满 4 GiB 会回绕,比较序号要用模 2^32 的差。高速网络里回绕很快,所以需要时间戳选项的 PAWS。</p>'),
     ('两个方向', '<p>每个方向各有独立的序号空间。</p>')],
    steps,
    [ENV_W + '。全部在 lo0 上做;第三节的 4.5 GiB 传输只抓每个包的头部(snaplen 96),抓包丢掉了一部分包(抓到 263593 个数据段,实际更多),但回绕点在抓到的包里;序号取相对值时减去各自的 ISN',
     '没有验证:序号回绕在 en0 真实网络上多久发生一次;乱序时确认号的变化(见快速重传与 SACK);窗口与序号的关系(见滑动窗口);序号随机化之外的 ISN 攻击(RFC 6528)'],
    '序号与确认号')
